c='p11';B='NGHỀ 2'
S=[]
S.append(TITLE('TIN HỌC · NGHỀ 2','ĐẠO ĐỨC, PHÁP LUẬT<br>VÀ BẢN QUYỀN SỐ','Giao tiếp trên mạng, ứng xử nhân văn, bản quyền, giấy phép (thương mại, MIT/GPL, Creative Commons), dữ liệu cá nhân và dùng AI có trách nhiệm.',['nhân văn','bản quyền','giấy phép','dữ liệu cá nhân','trung thực']))
S.append(goals(c,B,['Nêu <b>ưu và nhược điểm</b> của giao tiếp trên mạng.','Ứng xử <b>nhân văn</b> khi gặp bắt nạt, tin giả.','Phân biệt <b>vi phạm</b> và <b>sử dụng hợp lệ</b> (trích dẫn, Creative Commons, mã nguồn mở).','Nêu nguyên tắc <b>thu thập dữ liệu cá nhân</b>.','Dùng <b>AI và mã nguồn</b> có trách nhiệm, ghi nguồn.'],['Giao tiếp trên mạng','Ứng xử nhân văn','Bản quyền và giấy phép','Dữ liệu cá nhân','Trách nhiệm nghề']))
