S.append(S2(c,B+' · 1','Hiểu sai tin nhắn',card('Cách phòng tránh',P('Hiểu sai <b>xảy ra cả khi nhắn văn bản bằng tiếng mẹ đẻ</b>, không riêng ngoại ngữ hay video.','Diễn đạt <b>rõ ràng</b>, dùng biểu tượng cảm xúc khi phù hợp, hỏi lại khi chưa chắc.','Tin nhắn “đã viết bằng chữ” <b>vẫn có thể bị hiểu sai</b>.')),KEY('Không bao giờ nói “văn bản thì không thể hiểu sai”.')))
S.append(S2(c,B+' · 2','Tính nhân văn trên mạng',card('Hành vi đúng',P('<b>Phản hồi ý kiến trái chiều một cách tôn trọng</b>; <b>kiểm chứng tin</b> trước khi chia sẻ.','Tôn trọng <b>danh dự</b> và <b>quyền riêng tư</b> của người khác: đăng ảnh bạn phải <b>xin phép</b>.')),T(tr('Hành vi','Đánh giá',h=True)+tr('Chia sẻ ngay tin giật gân','<b>Sai</b>')+tr('Bình luận mỉa mai để câu lượt xem','<b>Sai</b>')+tr('Đăng ảnh bạn chưa hỏi ý kiến “cho vui”','<b>Sai</b>')+tr('Kiểm chứng rồi mới chia sẻ','<b>Đúng</b>'))))
S.append(S2(c,B+' · 2','Khi bạn bị công kích trên mạng',card('Cách ứng xử',STEPS(['<b>Không công kích</b> lại, không chia sẻ, không “thích” bài công kích.','<b>Nhắn tin động viên</b> bạn.','<b>Báo người có trách nhiệm</b> (thầy cô, quản trị nền tảng).'])),KEY('Không tiếp tay cho hành vi tiêu cực: im lặng và “thích” bài công kích cũng là sai.')))
S.append(S2(c,B+' · 3','Bản quyền và trung thực',card('Quyền tác giả',P('Nội dung số (bài viết, ảnh, mã nguồn) được <b>bảo hộ bản quyền</b>.','<b>Vi phạm</b>: sao chép bài có bản quyền, <b>bỏ tên tác giả</b>, đăng như của mình; dùng ảnh bất kì tìm trên mạng.','<b>Hợp lệ</b>: trích dẫn <b>đoạn ngắn kèm nguồn đầy đủ</b>; chia sẻ <b>liên kết</b> tới bài gốc; dùng ảnh có giấy phép <b>Creative Commons</b> và ghi nguồn.')),T(tr('Hành vi','Kết luận',h=True)+tr('Chia sẻ link bài gốc','hợp lệ')+tr('Ảnh CC + ghi nguồn','hợp lệ')+tr('Trích ngắn có nguồn','hợp lệ')+tr('Xoá tên tác giả rồi đăng','<b>vi phạm</b>'))))
S.append(S2(c,B+' · 3','Giấy phép phần mềm và mã nguồn',card('Các loại giấy phép',T(tr('Loại','Cho phép',h=True)+tr('<b>Thương mại, độc quyền</b>','dùng theo điều khoản; <b>không</b> tự sửa, phân phối lại')+tr('<b>Nguồn mở</b> (MIT, GPL)','<b>dùng, sửa đổi, phân phối lại</b> mã nguồn theo điều kiện giấy phép')+tr('<b>Dùng thử</b>','giới hạn thời gian'))),KEY('Sao chép mã giấy phép hạn chế vào sản phẩm thương mại: <b>vi phạm bản quyền</b> dù đổi tên biến.')))
S.append(S2(c,B+' · 3','“Công khai trên mạng” có nghĩa là được dùng?',card('Hiểu đúng',P('Mã nguồn công khai <b>vẫn được bảo hộ</b>; phải <b>tuân thủ giấy phép</b> của tác giả.','Không hợp lệ chỉ vì <b>sản phẩm chưa có người mua</b> hay vì <b>đổi tên biến</b>.','Trung thực: <b>ghi rõ nguồn tài liệu, mã và ảnh</b> đã dùng; không nhận công sức của cả nhóm về mình.')),KEY('<b>Công khai ≠ miễn phí dùng</b> không điều kiện.')))
S.append(S2(c,B+' · 4','Dữ liệu cá nhân',card('Thu thập hợp pháp',P('Nguyên tắc: <b>mục đích rõ</b>, <b>có sự đồng ý</b>, <b>mức cần thiết</b>.','Không thu càng nhiều càng tốt; không thông báo sau; <b>không bán</b> cho bên thứ ba.','Người quản trị dữ liệu: <b>bảo vệ thông tin cá nhân, cấp quyền tối thiểu</b>, vẫn phải <b>sao lưu</b>.')),T(tr('Hành vi','Đúng?',h=True)+tr('Chia sẻ điểm học sinh cho bên quảng cáo','<b>Sai</b>')+tr('Cấp toàn quyền cho mọi giáo viên','<b>Sai</b> (quyền tối thiểu)')+tr('Đăng công khai dữ liệu khách hàng','<b>Sai</b>')+tr('Dùng đúng mục đích, bảo mật','<b>Đúng</b>'))))
S.append(S2(c,B+' · 5','Dùng AI sinh nội dung có trách nhiệm',card('Biện pháp giảm rủi ro',P('<b>Kiểm chứng</b> với nguồn tin cậy; <b>ghi rõ phần có AI hỗ trợ</b> khi nộp bài.','Không sao chép nguyên văn rồi nộp như của mình; không tin tuyệt đối.','Không đưa dữ liệu cá nhân nhạy cảm vào công cụ AI.')),KEY('AI có thể <b>sai</b> và <b>bịa</b>; người dùng chịu trách nhiệm cuối cùng.')))
S.append(SELF(c,B+' · 6','Tự kiểm tra 1: hành vi vi phạm','Hành vi nào vi phạm: chia sẻ link bài gốc; dùng ảnh Creative Commons ghi nguồn; trích đoạn ngắn có nguồn; sao chép bài, bỏ tên tác giả rồi đăng như của mình?','',P('Chỉ hành vi <b>cuối</b> là vi phạm đạo đức và pháp luật.'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra 2: thu thập dữ liệu','Nguyên tắc ưu tiên khi thu thập thông tin người dùng hợp pháp?','',P('Thu thập <b>có mục đích rõ, có sự đồng ý, ở mức cần thiết</b>.'),22))
S.append(SELF(c,B+' · 6','Tự kiểm tra (HSG): đúng hay sai?','(a) Mã nguồn công khai thì tự do dùng. (b) Đổi tên biến thì hết vi phạm. (c) Giấy phép MIT/GPL cho phép sửa và phân phối lại theo điều kiện. (d) Nhược điểm giao tiếp mạng: thiếu tín hiệu phi ngôn ngữ. (e) Thấy bạn bị công kích, nên chia sẻ bài để mọi người bình luận.','',P('(a) <b>Sai</b>.','(b) <b>Sai</b>.','(c) <b>Đúng</b>.','(d) <b>Đúng</b>.','(e) <b>Sai</b>.'),20))
